import json
import pytest
from pathlib import Path
from project.agents.munshif_testing.agent import generate_tests

def test_generate_tests_missing_fields(tmp_path: Path):
    (tmp_path / "mod.py").write_text("pass", encoding="utf-8")
    impact = {"source_path": ".", "reports": [{"changed_file": "mod.py"}]}
    def model(_):
        # All fields are present but some are empty after stripping
        return json.dumps({"scenarios": [{"title": "incomplete", "rationale": "", "assumptions": "", "test_code": ""}]})
    with pytest.raises(ValueError):
        generate_tests(tmp_path, impact, model)
